"""Phase 7 step 10: write the fitted VTOL parameters as a flight profile (spec 8.7, A93):
configs/flight_profiles/px4_sitl_vtol_proxy.toml, from pipeline/calib/vtol_fitted_params.json.
Every value stays a placeholder (assumption = true) whose source is the SITL proxy fit."""

import json

from common import CALIB, REPO
from vtol_fit import profile_text

PROFILE = REPO / "configs" / "flight_profiles" / "px4_sitl_vtol_proxy.toml"
HEADER = """# VTOL flight profile fitted to PX4 SITL flights of the scaled standard VTOL (docs/vtol.md).
# Generated by `pipeline/run.sh calib vtol` from pipeline/calib/vtol_fitted_params.json; do not
# edit. SITL has no power model: powers come from the energy proxy of spec A57 and A92, so every
# value is a placeholder (assumption = true) with source px4-sitl-proxy. Bootstrap std per key:
"""


def main() -> None:
    fitted = json.loads((CALIB / "vtol_fitted_params.json").read_text())
    std = "".join(f"#   {k}: {v}\n" for k, v in fitted["std"].items())
    PROFILE.write_text(HEADER + std + "\n" + profile_text(fitted["params"]))
    print(f"wrote {PROFILE.relative_to(REPO)}")


if __name__ == "__main__":
    main()
